function DRLViewAssemblyTier(aIndex: Integer; const aEnglish: AnsiString): AnsiString;
const IDs: array[0..2] of AnsiString = ('view.assembly-tier.basic','view.assembly-tier.advanced','view.assembly-tier.master');
begin
  if (aIndex < Low(IDs)) or (aIndex > High(IDs)) then Exit(aEnglish);
  Exit(DRLText(IDs[aIndex], aEnglish));
end;

function DRLViewBadgeTier(aIndex: Integer; const aEnglish: AnsiString): AnsiString;
const IDs: array[1..6] of AnsiString = ('view.badge-tier.bronze','view.badge-tier.silver','view.badge-tier.gold','view.badge-tier.platinum','view.badge-tier.diamond','view.badge-tier.angelic');
begin
  if (aIndex < Low(IDs)) or (aIndex > High(IDs)) then Exit(aEnglish);
  Exit(DRLText(IDs[aIndex], aEnglish));
end;
